def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    maximum = max(v1, v2)

    return {
        "value": maximum,
        "trace": {
            "v1": v1,
            "v2": v2,
            "maximum": maximum,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
